def zhang(a):
 im=a.astype(np.uint8).copy();changed=True
 while changed:
  changed=False
  for it in [0,1]:
   p=np.pad(im,1)
   P2=p[:-2,1:-1];P3=p[:-2,2:];P4=p[1:-1,2:];P5=p[2:,2:];P6=p[2:,1:-1];P7=p[2:,:-2];P8=p[1:-1,:-2];P9=p[:-2,:-2]
   ns=[P2,P3,P4,P5,P6,P7,P8,P9]
